// Extract text from either voice transcription or text message
const isVoice = $input.first().json.message?.voice !== undefined;
let messageText = '';
let chatId = $input.first().json.message.chat.id;
let messageId = $input.first().json.message.message_id;

if (isVoice) {
  // From voice transcription (this would come from Groq)
  messageText = 'Voice transcription would go here';
} else {
  // From text message
  messageText = $input.first().json.message.text;
}

return {
  text: messageText,
  chatId: chatId,
  messageId: messageId,
  isVoice: isVoice,
  timestamp: new Date().toISOString()
};

