// Parse AI response and prepare confirmation
let aiResponse;
try {
  aiResponse = JSON.parse($json.choices[0].message.content);
} catch (e) {
  return {
    error: true,
    message: 'Failed to parse AI response',
    chatId: $input.all()[0].json.chatId
  };
}

const tasks = aiResponse.tasks || [];
const summary = aiResponse.summary || 'No tasks identified';

// Build detailed confirmation message
let confirmationText = `✅ **I understood your request!**\n\n`;
confirmationText += `📋 **Summary:** ${summary}\n\n`;

if (tasks.length === 0) {
  confirmationText += `❓ No specific tasks identified. Please provide more details.`;
} else {
  confirmationText += `🎯 **I found ${tasks.length} task(s):**\n\n`;

  tasks.forEach((task, index) => {
    const emoji = {
      'bug': '🐛',
      'feature': '✨',
      'ui': '🎨',
      'technical': '🔧'
    }[task.type] || '📌';

    const priority = {
      'high': '🔴 HIGH',
      'medium': '🟡 MEDIUM',
      'low': '🟢 LOW'
    }[task.priority] || '';

    const actionEmoji = {
      'github': '🐙',
      'todo': '📝',
      'claude': '🤖',
      'feedback': '💬'
    }[task.action] || '📋';

    const actionText = {
      'github': 'Create GitHub Issue',
      'todo': 'Add to Todo List',
      'claude': 'Send to Claude Code',
      'feedback': 'Log as Feedback'
    }[task.action] || task.action;

    confirmationText += `**${index + 1}.** ${emoji} **${task.title}**\n`;
    confirmationText += `   Priority: ${priority}\n`;
    confirmationText += `   Component: 📁 ${task.component}\n`;
    confirmationText += `   Action: ${actionEmoji} ${actionText}\n`;
    confirmationText += `   _${task.description}_\n\n`;
  });

  confirmationText += `\n🚀 **Next Steps:**\n`;
  confirmationText += `I'll now process these tasks and send them to the appropriate systems.\n`;
  confirmationText += `You'll receive confirmation as each task is completed!`;
}

return {
  tasks: tasks,
  summary: summary,
  confirmationText: confirmationText,
  chatId: $input.all()[0].json.chatId,
  messageId: $input.all()[0].json.messageId,
  hasError: false
};
